// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        // The general rule: setOwner succeeds only if caller is the admin (the deployer).
        // In the reference, admin is the deployer (address(this) in constructor is test contract).
        // So success iff caller == address(this).
        bool expected = (caller == address(this));
        assertTrue(success == expected);
    }
}

