// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this)); // admin is address(this) because constructor sets admin = msg.sender
        address originalOwner = c.owner();
        // The call will revert because caller is not admin
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, address(0x123)));
        assertTrue(!success, "non-admin should revert");
        assertTrue(c.owner() == originalOwner, "owner should not change");
    }
}

