contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Only test when caller is the admin (the deployer)
        vm.assume(_owner != address(0));

        bool success = c.setOwner(_owner);

        // The rule: after successful call by admin, owner should equal _owner
        assertTrue(success && c.owner() == _owner);
    }
}

